package it.gm83.pacewidgets;
import android.app.*;
import android.appwidget.AppWidgetManager;
import android.os.*;
import android.content.*;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
public final class SetupActivity extends Activity {
 private int widget=-1;private boolean busy=false,registered=false;private String fixed="",panel="devices";private Set<String> favorites=new HashSet<>();private LinearLayout column;
 private final ExecutorService executor=Executors.newSingleThreadExecutor();
 private final BroadcastReceiver changed=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if(!isFinishing())render();}};
 @Override public void onCreate(Bundle state){super.onCreate(state);setResult(RESULT_CANCELED);widget=state==null?getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1):state.getInt("widget",-1);if(PaceLogin.callback(getIntent().getData()))widget=PaceLogin.pendingWidget(this);loadSettings();getWindow().setStatusBarColor(Color.rgb(248,249,252));getWindow().setNavigationBarColor(Color.rgb(248,249,252));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);render();handle(getIntent());}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("widget",widget);}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(PaceLogin.callback(intent.getData()))widget=PaceLogin.pendingWidget(this);else if(intent.hasExtra(AppWidgetManager.EXTRA_APPWIDGET_ID))widget=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);loadSettings();handle(intent);}
 @Override protected void onResume(){super.onResume();IntentFilter filter=new IntentFilter(Jobs.CHANGED);androidx.core.content.ContextCompat.registerReceiver(this,changed,filter,androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);registered=true;render();if(PaceStore.connected(this))Jobs.refresh(this,true);}
 @Override protected void onPause(){if(registered){unregisterReceiver(changed);registered=false;}super.onPause();}
 @Override protected void onDestroy(){executor.shutdown();super.onDestroy();}
 private void loadSettings(){fixed=widget==-1?"":PaceStore.prefs(this).getString("board:"+widget,"");panel=widget==-1?"devices":PaceStore.prefs(this).getString("panel:"+widget,"devices");favorites=widget==-1?new HashSet<>():PaceStore.favorites(this,widget);}
 private void handle(Intent intent){Uri uri=intent.getData();if(PaceLogin.callback(uri)){intent.setData(null);run(()->{PaceLogin.complete(this,uri);Jobs.refresh(this,true);});}}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(LinearLayout parent,String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(Color.rgb(36,43,54));if(bold)t.setTypeface(null,android.graphics.Typeface.BOLD);t.setPadding(0,dp(8),0,dp(8));parent.addView(t);return t;}
 private Button button(LinearLayout parent,String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(ColorStateList.valueOf(Color.rgb(183,69,10)));b.setMinHeight(dp(48));b.setEnabled(!busy);parent.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->action.run());return b;}
 private void render(){
  FrameLayout outer=new FrameLayout(this);outer.setBackgroundColor(Color.rgb(248,249,252));ScrollView scroll=new ScrollView(this);int width=getResources().getConfiguration().screenWidthDp>760?dp(720):-1;FrameLayout.LayoutParams frame=new FrameLayout.LayoutParams(width,-1,Gravity.CENTER_HORIZONTAL);outer.addView(scroll,frame);column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setPadding(dp(20),dp(24),dp(20),dp(24));scroll.addView(column);setContentView(outer);
  ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.pace_logo);logo.setContentDescription("Logo PACE");column.addView(logo,new LinearLayout.LayoutParams(dp(64),dp(64)));text(column,"PACE Widgets",28,true);text(column,"powered by #gm83",12,false);
  if(busy)text(column,"Operazione in corso…",14,false);String message=PaceStore.message(this);if(!message.isEmpty())text(column,message,14,false);
  if(!PaceStore.connected(this)){text(column,"I tuoi dispositivi, subito sulla Home.",20,true);text(column,"Accedi con lo stesso account Google o email che usi in PACE. Le autorizzazioni sono quelle assegnate dall’amministratore.",16,false);button(column,"Accedi a PACE",()->{try{PaceLogin.begin(this,widget);}catch(Exception e){PaceStore.message(this,"Impossibile aprire l’accesso. Installa o abilita un browser sul tablet.");render();}});return;}
  JSONObject account=PaceStore.load(this);text(column,"Account visualizzato",13,false);text(column,account.optString("userName","PACE"),18,true);JSONArray boards=Models.array(account,"boards");if(boards.length()==0){text(column,"Caricamento delle plance autorizzate…",16,false);button(column,"Aggiorna",()->Jobs.refresh(this,true));logout();return;}
  List<String> names=new ArrayList<>(),ids=new ArrayList<>();for(int i=0;i<boards.length();i++){JSONObject b=Models.item(boards,i);names.add(b.optString("name"));ids.add(b.optString("id"));}
  text(column,"Plancia nell’app",16,true);Spinner picker=new Spinner(this);picker.setContentDescription("Plancia nell’app");picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));column.addView(picker,new LinearLayout.LayoutParams(-1,dp(52)));int current=ids.indexOf(PaceStore.selected(this));picker.setSelection(Math.max(0,current));picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(!ids.get(pos).equals(PaceStore.selected(SetupActivity.this))){PaceStore.select(SetupActivity.this,ids.get(pos));PaceWidget.refreshAll(SetupActivity.this);Jobs.refresh(SetupActivity.this,false);if(fixed.isEmpty())favorites.clear();render();}}});
  if(widget!=-1){text(column,"Questo widget",20,true);CheckBox follow=new CheckBox(this);follow.setText("Segui la plancia scelta nell’app");follow.setChecked(fixed.isEmpty());column.addView(follow);follow.setOnCheckedChangeListener((b,on)->{fixed=on?"":PaceStore.selected(this);favorites.clear();render();});if(!fixed.isEmpty()){Spinner target=new Spinner(this);target.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));column.addView(target,new LinearLayout.LayoutParams(-1,dp(52)));target.setSelection(Math.max(0,ids.indexOf(fixed)));target.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(!fixed.equals(ids.get(pos))){fixed=ids.get(pos);favorites.clear();Jobs.board(SetupActivity.this,fixed);render();}}});}
   if(account.optBoolean("isSuperadmin")){CheckBox usage=new CheckBox(this);usage.setText("Mostra i consumi Firebase del progetto");usage.setChecked("usage".equals(panel));column.addView(usage);usage.setOnCheckedChangeListener((b,on)->{panel=on?"usage":"devices";render();});}
   button(column,"Salva widget",()->{PaceStore.prefs(this).edit().putString("board:"+widget,fixed).putString("panel:"+widget,panel).putStringSet("favorites:"+widget,new HashSet<>(favorites)).commit();PaceWidget.render(this,AppWidgetManager.getInstance(this),widget);Jobs.refresh(this,false);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widget));finish();});
  }
  String boardId=widget!=-1&&!fixed.isEmpty()?fixed:PaceStore.selected(this);JSONObject board=Models.board(account,boardId);if(board!=null){text(column,board.optString("name"),22,true);long observed=board.optLong("observedAt");text(column,PaceWidget.time(observed),12,false);List<JSONObject> devices=Models.devices(board,Collections.emptySet());if(devices.isEmpty())text(column,"Aggiorna per caricare i dispositivi. Cancelli e comandi a impulso restano disponibili nella webapp.",15,false);for(JSONObject device:devices){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setMinimumHeight(dp(68));column.addView(row,new LinearLayout.LayoutParams(-1,-2));TextView led=new TextView(this);led.setText("●");led.setTextColor(Models.color(device));led.setTextSize(24);row.addView(led,new LinearLayout.LayoutParams(dp(28),-2));LinearLayout caption=new LinearLayout(this);caption.setOrientation(LinearLayout.VERTICAL);row.addView(caption,new LinearLayout.LayoutParams(0,-2,1));text(caption,device.optString("name"),15,true).setPadding(0,0,0,0);text(caption,Models.caption(device),12,false).setPadding(0,0,0,0);
   if(widget!=-1){CheckBox favorite=new CheckBox(this);favorite.setContentDescription("Preferito "+device.optString("name"));favorite.setChecked(favorites.contains(device.optString("id")));row.addView(favorite);favorite.setOnCheckedChangeListener((b,on)->{if(on)favorites.add(device.optString("id"));else favorites.remove(device.optString("id"));});}
   if(Models.controllable(device))for(String state:new String[]{"on","off"}){Button command=new Button(this);command.setAllCaps(false);command.setText("on".equals(state)?"ON":"OFF");command.setTextColor("on".equals(state)?0xff16814a:0xffcc3241);row.addView(command,new LinearLayout.LayoutParams(dp(60),dp(48)));command.setOnClickListener(v->Jobs.command(this,boardId,device.optString("id"),state));}
  }}
  if(widget!=-1)text(column,"Se non selezioni preferiti vengono mostrati tutti. I dispositivi accesi hanno sempre la precedenza; l’elenco del widget si scorre con il dito.",14,false);
  button(column,"Aggiorna dispositivi",()->Jobs.refresh(this,true));text(column,SecureStore.read(this,"push-status","Preparazione degli aggiornamenti automatici…"),13,false);
  if(widget==-1){button(column,"Aggiungi un widget",()->{AppWidgetManager manager=AppWidgetManager.getInstance(this);if(android.os.Build.VERSION.SDK_INT>=26&&manager.isRequestPinAppWidgetSupported())manager.requestPinAppWidget(new ComponentName(this,PaceWidget.class),null,null);else new AlertDialog.Builder(this).setMessage("Tieni premuta la Home, scegli Widget e cerca PACE Widgets.").setPositiveButton("OK",null).show();});}
  button(column,"Apri la webapp PACE",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(PaceApi.ORIGIN+"/app/index.html"))));logout();
 }
 private void logout(){button(column,"Scollega PACE Widgets",()->new AlertDialog.Builder(this).setMessage("Vuoi scollegare solo PACE Widgets su questo tablet? Le programmazioni sul server continuano a funzionare.").setNegativeButton("Annulla",null).setPositiveButton("Scollega",(d,w)->run(()->{PaceApi.request(this,"/api/widgets/logout",new JSONObject());PaceStore.signedOut(this);com.google.firebase.messaging.FirebaseMessaging.getInstance().setAutoInitEnabled(false);com.google.firebase.messaging.FirebaseMessaging.getInstance().deleteToken();Jobs.changed(this);})).show());}
 private interface Action{void run()throws Exception;}
 private void run(Action action){if(busy)return;busy=true;render();executor.execute(()->{try{action.run();}catch(Exception e){PaceStore.message(this,e instanceof PaceApi.Failure?e.getMessage():"Operazione non riuscita. Riprova quando la connessione è disponibile.");}runOnUiThread(()->{busy=false;if(!isFinishing())render();});});}
}
